SELECT (DATE_TRUNC('HOUR', "LOAD_HOUR")) AS "TIME_BUCKET", SUM(QUERY_COUNT) AS "WH_QUERY_COUNT" FROM (SELECT "WAREHOUSE_NAME" AS WAREHOUSE_NAME, (DATE_TRUNC('HOUR', (TRY_TO_TIMESTAMP_NTZ("START_TIME")))) AS LOAD_HOUR, COUNT(*) AS QUERY_COUNT, SUM("QUEUED_OVERLOAD_TIME") AS QUEUED_OVERLOAD_MS, SUM("QUEUED_PROVISIONING_TIME") AS QUEUED_PROVISIONING_MS, SUM("TOTAL_ELAPSED_TIME") AS ELAPSED_MS, SUM("EXECUTION_TIME") AS EXECUTION_MS FROM query_history GROUP BY 1, 2) AS base GROUP BY (DATE_TRUNC('HOUR', "LOAD_HOUR")) ORDER BY "WH_QUERY_COUNT" DESC NULLS LAST, "TIME_BUCKET" LIMIT 100
